styl:
.brad-full { border-radius: 32px !important; }
.white-bg { background-color: #fff; }
.middle-title { font-family: Helvetica !important;
  font-weight: 700;
  font-size: 32px;
  line-height: 42px;
  color: #393a44;
  vertical-align: middle; }
@media screen and (max-width: 600px) {
  .middle-title { font-size: 28px !important;
    line-height: 34px !important; }
}
.text { font-family: Helvetica !important;
  font-size: 18px;
  color: #393a44;
  letter-spacing: 0;
  line-height: 26px;
  font-weight: 400; }
.text.bold { font-weight: 700; }
.pb8 { padding-bottom: 8px; }
.pb16 { padding-bottom: 16px; }
.pb32 { padding-bottom: 32px; }
.pb44 { padding-bottom: 44px; }
.pt44 { padding-top: 44px; }
.h-12 { font-size: 8px;
  line-height: 12px;
  height: 12px; }
.padd { padding: 24px 24px 20px 24px; }
@media screen and (max-width: 600px) {
  .padd { padding: 24px !important; }
}
.left-block { display: inline-block;
  width: 228px;
  min-height: 280px;
  background: #f9f9f9;
  border-radius: 24px;
  margin-right: 10px;
  vertical-align: top; }
@media screen and (max-width: 600px) {
  .left-block { display: block !important;
    margin: 0 auto 16px !important;
    min-height: auto !important;
    height: auto !important; }
}
.right-block { display: inline-block;
  width: 228px;
  min-height: 280px;
  background: #f9f9f9;
  border-radius: 24px;
  vertical-align: top; }
@media screen and (max-width: 600px) {
  .right-block { display: block !important;
    margin: 0 auto 16px !important;
    min-height: auto !important;
    height: auto !important; }
}
.big-block { background: url("https://fsms.quadcode.com/storage/public/d7/bn/05ansqgk5ucdfopg/1-2-2-2-bg.png") center no-repeat;
  background-color: #f9f9f9 !important;
  background-size: cover !important;
  border-radius: 24px; }
@media screen and (max-width: 600px) {
  .big-block { width: 230px !important;
    background: #f9f9f9 !important;
    margin: 0 auto !important; }
}
.big-block-2 { background: url("https://fsms.quadcode.com/storage/public/d7/bn/05ansqgk5ucdfop0/1-2-2-3-bg.png") center no-repeat;
  background-color: #f9f9f9 !important;
  background-size: cover !important;
  border-radius: 24px; }
@media screen and (max-width: 600px) {
  .big-block-2 { width: 230px !important;
    background: #f9f9f9 !important;
    margin: 0 auto !important; }
}
.left-side { display: inline-block;
  padding: 24px 0 24px 24px;
  width: 240px; }
@media screen and (max-width: 600px) {
  .left-side { display: block !important;
    width: auto !important;
    padding: 20px 20px 0 20px !important; }
}
.right-img { display: inline-block;
  width: 1px;
  max-width: 0.1px;
  float: none;
  vertical-align: bottom; }
@media screen and (max-width: 600px) {
  .right-img { display: block !important;
    float: none !important;
    width: 100% !important;
    max-width: 100% !important; }
}
@media screen and (max-width: 600px) {
  .center-mob { text-align: center !important; }
}
